package com.commercecore.wishlist;import org.springframework.data.jpa.repository.*;import java.util.*;public interface WishlistItemRepository extends JpaRepository<WishlistItem,UUID>{@EntityGraph(attributePaths={"product","product.category","variant"})List<WishlistItem> findAllByUserIdOrderByCreatedAtAsc(UUID userId);Optional<WishlistItem> findByIdAndUserId(UUID id,UUID userId);Optional<WishlistItem> findByUserIdAndProductIdAndVariantIsNull(UUID userId,UUID productId);Optional<WishlistItem> findByUserIdAndVariantId(UUID userId,UUID variantId);}
